package dev.youth; import static org.junit.jupiter.api.Assertions.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;
class SchedulerTest {final Instant now=Instant.parse("2030-01-01T09:00:00Z");@Test void prioritizesAndSplitsAvailability(){var s=new Scheduler();var p=s.schedule(List.of(new Scheduler.Request("low",30,1,now.plusSeconds(7200),Set.of()),new Scheduler.Request("high",30,5,now.plusSeconds(7200),Set.of("first-aid"))),List.of(new Scheduler.Slot("v",now,now.plusSeconds(3600),Set.of("first-aid"))));assertEquals(List.of("high","low"),p.assignments().stream().map(Scheduler.Assignment::request).toList());}@Test void explainsMissingSkill(){var p=new Scheduler().schedule(List.of(new Scheduler.Request("r",30,3,now.plusSeconds(3600),Set.of("coding"))),List.of(new Scheduler.Slot("v",now,now.plusSeconds(3600),Set.of("art"))));assertTrue(p.unassigned().containsKey("r"));}}
